export function ComparisonPanel(n){return`<div class="comparison-panel">\n    <h3>Then vs. Now, at a Glance</h3>\n    <div class="comparison-table-wrap">\n      <table class="comparison-table">\n        <thead>\n          <tr>\n            <th>Period</th>\n            <th>Historical System</th>\n            <th>Modern Equivalent</th>\n          </tr>\n        </thead>\n        <tbody>${n.map(n=>`<tr>\n        <td class="comparison-year">${n.year}</td>\n        <td class="comparison-then">${n.then}</td>\n        <td class="comparison-now">${n.now}</td>\n      </tr>`).join("")}</tbody>\n      </table>\n    </div>\n  </div>`}